import { readFileSync } from 'fs';

/** Project rule IDs: sast-<language>-<number>, e.g. sast-python-0001. */
export const RULE_ID_PATTERN = /^sast-[a-z0-9-]+-\d{4,}$/;

/**
 * The rule ID catalog (src/config/opengrep/rule-ids.json, generated by
 * tools/generate-rule-ids.mjs) maps each opengrep-rules rule to a project ID.
 * Keys are the rule's directory inside opengrep-rules plus its id, dotted:
 * "python.django.security.injection.sql.sql-injection-using-raw".
 */
export interface RuleIdCatalogFile {
  source?: string;
  ids: Record<string, string>;
}

export class RuleIdCatalog {
  /** Every dotted suffix of every rule key -> project IDs whose key ends with it. */
  private readonly bySuffix = new Map<string, Set<string>>();

  constructor(ids: Record<string, string>) {
    for (const [projectId, key] of Object.entries(ids)) {
      const segments = key.split('.');
      for (let i = 0; i < segments.length; i++) {
        const suffix = segments.slice(i).join('.');
        const set = this.bySuffix.get(suffix) ?? new Set<string>();
        set.add(projectId);
        this.bySuffix.set(suffix, set);
      }
    }
  }

  /**
   * Project ID for an Opengrep check_id, or undefined. Opengrep prefixes rule ids with the
   * path of the rule file's directory, and that path depends on where the rules are
   * installed (/opt/opengrep-rules/python/... -> "opt.opengrep-rules.python...."). So the
   * longest dotted suffix of the check_id that identifies exactly one catalog rule wins.
   * A check_id whose last part is already a project ID (the bundled rules) is returned as is.
   */
  lookup(checkId: string): string | undefined {
    const segments = checkId.split('.');
    const last = segments[segments.length - 1] ?? '';
    if (RULE_ID_PATTERN.test(last)) return last;
    // With a directory prefix, the rule's own directory must match too, so a user's rule that
    // reuses an opengrep-rules id in another directory keeps its own ID.
    const minSegments = Math.min(2, segments.length);
    for (let i = 0; i <= segments.length - minSegments; i++) {
      const matches = this.bySuffix.get(segments.slice(i).join('.'));
      if (!matches) continue;
      // A shorter suffix matches at least the same rules, so ambiguity here is final.
      return matches.size === 1 ? matches.values().next().value : undefined;
    }
    return undefined;
  }
}

export function loadRuleIdCatalog(file: string): RuleIdCatalog {
  let parsed: RuleIdCatalogFile;
  try {
    parsed = JSON.parse(readFileSync(file, 'utf8')) as RuleIdCatalogFile;
  } catch (error) {
    throw new Error(`Cannot read rule ID catalog ${file}: ${error instanceof Error ? error.message : String(error)}`);
  }
  if (!parsed || typeof parsed.ids !== 'object') throw new Error(`Rule ID catalog ${file} has no "ids" object`);
  for (const id of Object.keys(parsed.ids)) {
    if (!RULE_ID_PATTERN.test(id)) throw new Error(`Rule ID catalog ${file}: invalid project ID "${id}"`);
  }
  return new RuleIdCatalog(parsed.ids);
}

/** Project ID -> opengrep-rules key, for reports that show which rule file a finding came from. */
export function readRuleIdKeys(file: string): Record<string, string> {
  const parsed = JSON.parse(readFileSync(file, 'utf8')) as RuleIdCatalogFile;
  return parsed.ids ?? {};
}
